#ifndef RC_INVOKED

#include <string>
#include <vector>

struct RosterEntry
{
    int binResourceId;       // RCDATA id of the .bin payload
    int portraitResourceId;  // RCDATA id of the .png, 0 = none
    std::wstring name;       // character name or vehicle base name
    unsigned int ringColor;  // deterministic, see generator
    int buildNumber;         // 0 = character, 1/2/3 = vehicle build
};

struct VehicleGroup
{
    std::wstring baseName;
    std::vector<RosterEntry> builds;  // sorted by buildNumber
};

struct Franchise
{
    std::wstring name;
    int logoResourceId;
    std::vector<RosterEntry> characters;
    std::vector<VehicleGroup> vehicles;
};

struct BackgroundChoice
{
    std::wstring name;
    int resourceId;
};

struct PadSkin
{
    std::wstring name;
    int slotResourceIds[7];  // kPadCells order
};

struct WebFile
{
    const char* name;
    int resourceId;
};

extern const Franchise kFranchises[];
extern const size_t kFranchiseCount;
extern const BackgroundChoice kBackgroundChoices[];
extern const size_t kBackgroundChoiceCount;
extern const WebFile kWebFiles[];
extern const size_t kWebFileCount;
extern const int kWordmarkResourceId;
extern const int kBackgroundResourceId;
extern const int kAppIconResourceId;
extern const int kUIFontResourceId;
extern const int kUIFontWebResourceId;
extern const int kWorldTileResourceId;
extern const int kCharactersTileResourceId;
extern const int kSettingsTileResourceId;
extern const int kPadBackgroundResourceIds[7];
extern const PadSkin kPadSkins[];
extern const size_t kPadSkinCount;
extern const int kCustomBinIconResourceId;
extern const int kSfxNavigateResourceId;
extern const int kSfxSelectResourceId;
extern const int kSfxMoveResourceId;
extern const int kSfxRemoveResourceId;
extern const int kTextfieldBarResourceId;
extern const int kLoadButtonResourceId;
extern const int kClearButtonResourceId;
extern const int kMoveButtonResourceId;
extern const int kScrollBarResourceId;
extern const int kByHarrysofResourceId;
extern const int kYButtonResourceId;
extern const int kSettingsTextResourceId;
extern const int kSortDefaultResourceId;
extern const int kSortUserResourceId;
extern const int kSortStarterResourceId;
// Single source of truth for the app version shown in the UI (web
// catalog's "version" field) - kept in lockstep with APP_VERSION
// below, which also stamps the exe's own FILEVERSION/ProductVersion.
extern const wchar_t kAppVersion[];
// [style][button]; style order Xbox, DualShock4, Switch, button
// order as in kButtonNames. 0 = no icon bundled for that button.
extern const int kControllerIconResourceIds[3][16];
extern const size_t kControllerIconStyleCount;
extern const size_t kControllerIconButtonCount;

#endif  // RC_INVOKED

